import{_ as e,o as t,c as a,ao as n}from"./chunks/framework.CDWQtUe5.js";const g=JSON.parse('{"title":"Control files","description":"","frontmatter":{},"headers":[],"relativePath":"data/control_files.md","filePath":"data/control_files.md","lastUpdated":null}'),i={name:"data/control_files.md"};function l(r,s,o,d,h,p){return t(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="Control-files" tabindex="-1">Control files <a class="header-anchor" href="#Control-files" aria-label="Permalink to &quot;Control files {#Control-files}&quot;">​</a></h1><p>Control files are plain <code>Key : value</code> text. Unknown keys, duplicate keys and missing required keys are all errors, so a typo is caught immediately rather than silently ignored. Anything after <code>#</code> is a comment, and any key you leave out takes its default.</p><h2 id="FwdCtrl-—-the-forward-solver" tabindex="-1"><code>FwdCtrl</code> — the forward solver <a class="header-anchor" href="#FwdCtrl-—-the-forward-solver" aria-label="Permalink to &quot;\`FwdCtrl\` — the forward solver {#FwdCtrl-—-the-forward-solver}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Write Frechet derivative : no</span></span></code></pre></div><ul><li><strong><code>Write Frechet derivative</code></strong> — <code>yes</code> keeps the sensitivity matrix after the run, as <code>sensitivity.jld2</code> in the run folder, if you want it for something else. Read it back with <code>LoadSensitivity3D</code>.</li></ul><h2 id="InvCtrl.GN-—-Gauss–Newton" tabindex="-1"><code>InvCtrl.GN</code> — Gauss–Newton <a class="header-anchor" href="#InvCtrl.GN-—-Gauss–Newton" aria-label="Permalink to &quot;\`InvCtrl.GN\` — Gauss–Newton {#InvCtrl.GN-—-Gauss–Newton}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Algorithm                         : GN</span></span>
<span class="line"><span>Initial damping factor lambda     : auto</span></span>
<span class="line"><span>Exit search when rms is less than : 1</span></span>
<span class="line"><span>Maximum number of iterations      : 20</span></span>
<span class="line"><span>Lambda cooling factor             : 2</span></span>
<span class="line"><span>Density bounds (kg/m3)            : -400 400</span></span>
<span class="line"><span>Max line search steps             : 12</span></span>
<span class="line"><span>Smallness weight                  : 0.04</span></span>
<span class="line"><span>Smoothing weight x                : 1</span></span>
<span class="line"><span>Smoothing weight y                : 1</span></span>
<span class="line"><span>Smoothing weight z                : 1</span></span>
<span class="line"><span>Sensitivity weighting             : sensitivity</span></span>
<span class="line"><span>Depth weighting exponent          : 2</span></span>
<span class="line"><span>Depth weighting z0 (m)            : auto</span></span>
<span class="line"><span>Error floor (mGal)                : 0</span></span>
<span class="line"><span>Error percent                     : 0</span></span>
<span class="line"><span>GN damping                        : 0.001</span></span>
<span class="line"><span>Maximum CG iterations             : 50</span></span>
<span class="line"><span>CG tolerance                      : 0.001</span></span>
<span class="line"><span>Invert padding                    : yes</span></span></code></pre></div><p>The ones that change your answer most:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Exit search when rms is less than</code></td><td style="text-align:right;">when to stop. <code>1</code> means &quot;fit the data to the size of the errors&quot;. Below 1 you are fitting noise.</td></tr><tr><td style="text-align:right;"><code>Density bounds (kg/m3)</code></td><td style="text-align:right;">hard limits on the density contrast. Set them from your rock types; they do a lot of the regularization work.</td></tr><tr><td style="text-align:right;"><code>Smallness weight</code></td><td style="text-align:right;">how strongly the model is pulled back to the prior. Raise it for a quieter model.</td></tr><tr><td style="text-align:right;"><code>Smoothing weight x/y/z</code></td><td style="text-align:right;">how strongly neighbours are tied together. Raise <code>z</code> to discourage vertical streaks.</td></tr><tr><td style="text-align:right;"><code>Sensitivity weighting</code></td><td style="text-align:right;"><code>sensitivity</code>, <code>depth</code> or <code>none</code>. Without one, everything piles up just under the stations.</td></tr><tr><td style="text-align:right;"><code>Error floor</code> / <code>Error percent</code></td><td style="text-align:right;">the error actually used is the largest of the file error, this floor, and this percentage of the datum. Use them when you do not trust the error column.</td></tr></tbody></table><p><code>auto</code> for lambda lets the solver pick a starting regularization weight from the problem itself; that is usually the right choice.</p><h2 id="InvCtrl.INR-—-neural-inversion" tabindex="-1"><code>InvCtrl.INR</code> — neural inversion <a class="header-anchor" href="#InvCtrl.INR-—-neural-inversion" aria-label="Permalink to &quot;\`InvCtrl.INR\` — neural inversion {#InvCtrl.INR-—-neural-inversion}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Algorithm                         : INR</span></span>
<span class="line"><span>Exit search when rms is less than : 1</span></span>
<span class="line"><span>Maximum number of iterations      : 1500</span></span>
<span class="line"><span>Density bounds (kg/m3)            : -400 400</span></span>
<span class="line"><span>Error floor (mGal)                : 0</span></span>
<span class="line"><span>Error percent                     : 0</span></span>
<span class="line"><span>Hidden width                      : 128</span></span>
<span class="line"><span>Hidden layers                     : 3</span></span>
<span class="line"><span>Fourier frequencies               : 4</span></span>
<span class="line"><span>Learning rate                     : 0.015</span></span>
<span class="line"><span>Coordinate scaling                : per-axis</span></span>
<span class="line"><span>Seed                              : 42</span></span>
<span class="line"><span>Divergence factor                 : 3</span></span>
<span class="line"><span>Maximum restarts                  : 3</span></span>
<span class="line"><span>Learning rate schedule            : cosine</span></span>
<span class="line"><span>Learning rate floor               : 0.05</span></span>
<span class="line"><span>Frequency annealing               : 0.5</span></span>
<span class="line"><span>Invert padding                    : no</span></span></code></pre></div><p><strong><code>Maximum number of iterations</code> means training epochs here</strong>, so it wants thousands, not tens. The settings that matter:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Hidden width</code>, <code>Hidden layers</code></td><td style="text-align:right;">the network&#39;s capacity, which <em>is</em> the regularization. Wider and deeper means more detail and more risk of fitting noise.</td></tr><tr><td style="text-align:right;"><code>Fourier frequencies</code></td><td style="text-align:right;">how fine a spatial feature the network can express. More frequencies, sharper structure.</td></tr><tr><td style="text-align:right;"><code>Learning rate</code></td><td style="text-align:right;">too high and training swings; too low and it never arrives.</td></tr><tr><td style="text-align:right;"><code>Frequency annealing</code></td><td style="text-align:right;">releases the frequency bands coarse-to-fine over this fraction of the budget, so the network finds the broad shape before the detail.</td></tr><tr><td style="text-align:right;"><code>Seed</code></td><td style="text-align:right;">the network&#39;s initialisation. Change it to check your result is not an accident.</td></tr></tbody></table><h2 id="Invert-padding" tabindex="-1"><code>Invert padding</code> <a class="header-anchor" href="#Invert-padding" aria-label="Permalink to &quot;\`Invert padding\` {#Invert-padding}&quot;">​</a></h2><p>This key appears in both files and decides whether the geometric padding around your survey is free to change.</p><ul><li><p><strong>Gauss–Newton: <code>yes</code>.</strong> Its sensitivity or depth weighting already prices the volume of a padding cell, so those cells cost what they are worth.</p></li><li><p><strong>The INR: <code>no</code></strong> (the default for <code>InvCtrl.INR</code>). There is no term in the INR that pays for volume, so with the padding free the network fills those huge far-away cells to buy misfit cheaply and the run stalls.</p></li></ul><p>Because this is a property of the <em>algorithm</em> and not of the mesh, both runs can read the same <code>C3.dat</code>. <code>Summary.txt</code> records which setting was used.</p><h2 id="Reading-and-writing-them-from-Julia" tabindex="-1">Reading and writing them from Julia <a class="header-anchor" href="#Reading-and-writing-them-from-Julia" aria-label="Permalink to &quot;Reading and writing them from Julia {#Reading-and-writing-them-from-Julia}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fwd  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ReadFwdCtrl3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ctrl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ReadInvCtrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InvCtrl.GN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># picks GN or INR from the Algorithm line</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WriteInvCtrl3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InvCtrl.GN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InvCtrl3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(algorithm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :gn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, lambda </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                       target_rms </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, max_iter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p><code>WriteInvCtrl3D</code> and <code>WriteInvCtrlINR3D</code> always write every key, so they are a good way to see the full set of defaults.</p>`,21)])])}const u=e(i,[["render",l]]);export{g as __pageData,u as default};
